import{_ as e,o,c as a,a4 as u}from"./chunks/framework.9tZL7ZIQ.js";const i=JSON.parse('{"title":"1966年 · 十年复利奇迹","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1966年.md","filePath":"05_quotes/by-year/1966年.md"}'),l={name:"05_quotes/by-year/1966年.md"};function r(q,t,c,s,h,_){return o(),a("div",null,[...t[0]||(t[0]=[u('<h1 id="_1966年-·-十年复利奇迹" tabindex="-1">1966年 · 十年复利奇迹 <a class="header-anchor" href="#_1966年-·-十年复利奇迹" aria-label="Permalink to &quot;1966年 · 十年复利奇迹&quot;">​</a></h1><blockquote><p>&quot;这样的成绩，或许会由一位25岁、怀揣105100美元初始资金、身处适配其投资理念的市场环境的年轻人实现。但绝不会由36岁、管理54065345美元资金的我实现。&quot;——巴菲特（36岁）</p></blockquote><p>本页收录1966年致股东信中的经典语录。十年合伙公司业绩累计上涨1156%，而道指仅涨123%——这是巴菲特用行动证明&quot;跑赢市场&quot;可行的十年。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>&quot;过去十年的业绩，未来十年绝无可能复制，甚至无法接近。&quot;</p></blockquote><blockquote><p>&quot;一个25岁、怀揣105100美元初始资金的年轻人或许能实现那样的成绩。但绝不会由36岁、管理54065345美元资金的我实现。&quot;</p></blockquote><blockquote><p>&quot;显而易见，依赖零星优质机会的生意，前景不如机会源源不断的生意。&quot;</p></blockquote><blockquote><p>&quot;我不会涉足能力圈之外的投资。我对半导体、集成电路的了解，和对波兰五月甲虫交配习性的了解一样少。&quot;</p></blockquote><blockquote><p>&quot;我们不会追随市场流行的趋势投资——这类策略以预判市场走势为先、企业估值为后。我不会用自己的钱这么做，更不会用合伙人的钱冒险。&quot;</p></blockquote><blockquote><p>&quot;若优质机会俯拾皆是，这样的提前了结并无遗憾。但看看该类别的平均投资额便知，全年剩余时间我们再无新机会。&quot;</p></blockquote><blockquote><p>&quot;即便预期利润丰厚，我们也不会参与大概率引发重大人际问题的投资项目。&quot;</p></blockquote><blockquote><p>&quot;在集中持仓策略下，合伙人应充分准备好应对大幅跑输市场的时期，这是换取偶尔超额收益、追求长期优秀业绩的代价。&quot;</p></blockquote><blockquote><p>&quot;我绝不会为了追求更高长期收益，承担本金永久大幅亏损的风险。&quot;</p></blockquote><blockquote><p>&quot;作为合伙人，我向你们承诺：我会全力挖掘优质投资机会，最大化利用现有机会；若机会彻底枯竭，我会坦诚、及时告知。&quot;</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1966年是合伙公司成立十周年，实现了20.4%的收益，同期道指下跌15.6%，超额收益达36个百分点。但巴菲特在信中坦承：资金规模从10万增至5400万，优质机会却从&quot;源源不断&quot;变成&quot;一年2-3个&quot;，过去的高增长不可复制，未来需要下调预期。这是巴菲特首次公开承认规模对业绩的负面影响。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1966年-翻译-·-01-letters-1966年-年中信" tabindex="-1"><a href="/01_letters/1966年/翻译">01_letters/1966年/翻译</a> · <a href="/01_letters/1966年/年中信">01_letters/1966年/年中信</a> <a class="header-anchor" href="#_01-letters-1966年-翻译-·-01-letters-1966年-年中信" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1966年/翻译]] · [[→ 年中信|01_letters/1966年/年中信]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1966年/翻译">/01_letters/1966年/翻译</a></li></ul>',23)])])}const p=e(l,[["render",r]]);export{i as __pageData,p as default};
